[[GIST]] strict overlap, sort then merge

Sort by start time, then sweep with a min-heap of end times. For each booking, pop every end that's less than or equal to the current start, since touching is fine. Push the current end, and the answer is the largest heap size seen.

```js
function minRooms(bookings) {
  if (bookings.length === 0) return 0;
  const sorted = [...bookings].sort((a, b) => a[0] - b[0]);
  const heap = [];
  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && heap[l] < heap[m]) m = l;
        if (r < heap.length && heap[r] < heap[m]) m = r;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]];
        i = m;
      }
    }
    return top;
  };
  let rooms = 0;
  for (const [start, end] of sorted) {
    while (heap.length && heap[0] <= start) pop();
    push(end);
    rooms = Math.max(rooms, heap.length);
  }
  return rooms;
}
```

O(n log n) time, O(n) space. The heap holds only bookings still in progress, so its size is the rooms needed at that moment.

[[GIST]] sort by start, sweep with min-heap of ends

Sort by start time, then sweep with a min-heap of end times. For each booking, if the earliest end is less than or equal to the current start, pop it and reuse that room; otherwise push a new end. The heap size at the end is the answer, and an empty input returns 0.

```js
function minRooms(bookings) {
  if (bookings.length === 0) return 0;
  const sorted = [...bookings].sort((a, b) => a[0] - b[0]);
  const heap = []; // min-heap of end times

  const push = (x) => {
    heap.push(x);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]];
      i = p;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      while (true) {
        let s = i;
        const l = 2 * i + 1, r = 2 * i + 2;
        if (l < heap.length && heap[l] < heap[s]) s = l;
        if (r < heap.length && heap[r] < heap[s]) s = r;
        if (s === i) break;
        [heap[s], heap[i]] = [heap[i], heap[s]];
        i = s;
      }
    }
    return top;
  };

  for (const [start, end] of sorted) {
    if (heap.length && heap[0] <= start) pop();
    push(end);
  }
  return heap.length;
}
```

O(n log n) time, O(n) space. The `<=` is what lets a booking starting exactly when another ends share the room.

```python
def max_distinct_window_sum(nums, w):
    n = len(nums)
    if w <= 0 or w > n:
        return -1

    counts = {}
    window_sum = 0
    best = -1

    for i, x in enumerate(nums):
        counts[x] = counts.get(x, 0) + 1
        window_sum += x

        if i >= w:
            left = nums[i - w]
            window_sum -= left
            counts[left] -= 1
            if counts[left] == 0:
                del counts[left]

        if i >= w - 1 and len(counts) == w:
            if window_sum > best:
                best = window_sum

    return best
```

It slides a window of size w, keeping a count of each value inside it, so `len(counts) == w` means all w values are distinct. `best` starts at -1, so a genuine sum of zero still wins over the no-run case. Time is O(n) and space is O(w).

```python
def max_distinct_window_sum(nums, w):
    n = len(nums)
    if w <= 0 or w > n:
        return -1

    counts = {}
    window_sum = 0
    for i in range(w):
        counts[nums[i]] = counts.get(nums[i], 0) + 1
        window_sum += nums[i]

    best = window_sum if len(counts) == w else -1

    for i in range(w, n):
        out, inc = nums[i - w], nums[i]
        counts[out] -= 1
        if counts[out] == 0:
            del counts[out]
        counts[inc] = counts.get(inc, 0) + 1
        window_sum += inc - out
        if len(counts) == w and window_sum > best:
            best = window_sum

    return best
```

It keeps a count map and a running sum for the current window, sliding one element at a time; the window counts only when the map holds exactly w distinct values, and best starts at -1 so a genuine sum of zero still wins. Time is O(n) and space is O(w).
